from lib import *
S = SS('x105')
steps = [
    step("表单登录之后登录态存在哪里。未登录 GET /who:HTTP 302 到 /login。访问 /login 页面时拿到一个 JSESSIONID(前 8 位 6122A52D,这时还没有登录,是为存 CSRF 令牌创建的会话);POST /login 成功后 HTTP 302,Location 是 …/who?continue,响应里的 Set-Cookie 是 JSESSIONID=A5EAB0DE…; Path=/; HttpOnly——登录之后的 session id 和登录前不同,没有 Secure 也没有 SameSite 属性。带着这个 cookie GET /who:用户=alice;GET /sess:session 属性有 SPRING_SECURITY_CONTEXT 和 SPRING_SECURITY_SAVED_REQUEST,SPRING_SECURITY_CONTEXT 的类型是 SecurityContextImpl,maxInactiveInterval=1800 秒——登录态就存在服务端的 HttpSession 里,cookie 里只有 session id。", t=tl(S(1)), mark=lidx(S(1), 'Set-Cookie', 'GET /sess'), done=lidx(S(1), '未登录', '访问 /login 页面', 'GET /who → 用户'), b=bars([['登录前后 session id 是否相同(1=相同)', 0, '不同'], ['session 里的属性个数', 2, '2'], ['maxInactiveInterval(秒)', 1800, '1800'], ['cookie 的属性个数(Path、HttpOnly)', 2, '2']], 1800, mark=[0, 1], done=[2, 3]), kv=KV([['登录态', '存在服务端 HttpSession 的 SPRING_SECURITY_CONTEXT'], ['cookie', 'JSESSIONID,Path=/,HttpOnly,没有 Secure 和 SameSite'], ['登录前后', 'session id 变了'], ['超时', '默认 1800 秒']], ['登录态'])),
    step("会话固定攻击防护。默认配置下登录前后 session id 不同(上一步);把 sessionManagement 设成 sessionFixation().none() 之后:登录前 33D57952,登录后 33D57952,没有变——攻击者如果先诱导受害者使用一个已知的 session id,受害者登录之后这个 id 就成了已登录的凭据。所以默认的换 id 行为不要关。", t=tl(S(2)), mark=lidx(S(2), 'sessionFixation().none()'), done=[], b=bars([['默认:登录前后 session id 是否相同(1=相同)', 0, '不同(换了)'], ['sessionFixation().none():是否相同', 1, '相同(没换)']], 1, done=[0], mark=[1]), kv=KV([['默认', '登录成功换新的 session id'], ['none()', 'id 不变,会话固定攻击有机可乘'], ['建议', '不要关'], ['未验证', '具体的攻击演示']], ['默认'])),
    step("无状态:SessionCreationPolicy.STATELESS 加 httpBasic。带 Basic 的 GET /who:HTTP 200,用户=alice,session=没有,响应没有 Set-Cookie;不带凭据再请求一次:HTTP 401——服务端什么都没记住,每个请求都要带凭据(Basic 或 token)。无状态模式下 Spring Security 既不创建也不使用 HttpSession,SecurityContext 只存在于单个请求里。", t=tl(S(3)), mark=lidx(S(3), '不带凭据再请求一次'), done=lidx(S(3), '带 Basic 的 GET /who'), b=bars([['带 Basic 的请求状态码', 200, '200'], ['再不带凭据的请求状态码', 401, '401'], ['响应里 Set-Cookie 的条数', 0, '0']], 401, done=[0, 2], mark=[1]), kv=KV([['STATELESS', '不创建 HttpSession,没有 Set-Cookie'], ['每个请求', '都要重新带凭据'], ['SecurityContext', '只活在一个请求里'], ['适合', 'API + token / Basic']], ['STATELESS'])),
    step("自己写登录接口时,Spring Security 6 以后不再自动保存 SecurityContext。两个接口都用 AuthenticationManager 认证并 SecurityContextHolder.setContext:/api/login-nosave 不保存——本请求内 SecurityContextHolder 里是 alice,但响应没有 Set-Cookie(0 条),随后再 GET /who:HTTP 302 跳到 /login,等于没登录。/api/login-save 多调用了 HttpSessionSecurityContextRepository.saveContext:响应有 1 条 Set-Cookie,随后 GET /who:HTTP 200,用户=alice。也就是说「在 Holder 里设了 Authentication」只对当前请求有效,要在下一个请求里还有,必须显式保存到 SecurityContextRepository。", t=tl(S(4)), mark=lidx(S(4), '/api/login-nosave', '随后带着 Cookie GET /who → HTTP 302'), done=lidx(S(4), '/api/login-save', 'HTTP 200,用户=alice'), b=bars([['nosave:响应里 Set-Cookie 的条数', 0, '0'], ['nosave:随后 /who 的状态码', 302, '302'], ['save:响应里 Set-Cookie 的条数', 1, '1'], ['save:随后 /who 的状态码', 200, '200']], 302, mark=[0, 1], done=[2, 3]), kv=KV([['只 setContext', '本请求有效,下一个请求就没了'], ['saveContext', '写进 HttpSession,下一个请求读回来'], ['症状', 'nosave 之后 /who 302 跳回 /login'], ['Spring Security 6+', '不再自动保存,要显式调用']], ['只 setContext'])),
    step("退出登录。登录后拿到 CSRF 令牌,POST /logout 带令牌:HTTP 302,Location 是 /login?logout;响应里没有 Set-Cookie(服务端只是把 session 作废,没有下发删除 cookie 的指令)。拿着退出之前的旧 cookie 再 GET /who:HTTP 302 跳到 /login——旧 session id 在服务端已经失效。", t=tl(S(5)), mark=lidx(S(5), '拿着退出前的旧 Cookie'), done=lidx(S(5), 'POST /logout'), b=bars([['POST /logout 的状态码', 302, '302'], ['退出后旧 cookie 访问 /who 的状态码', 302, '302'], ['退出响应里 Set-Cookie 的条数', 0, '0']], 302, done=[0, 2], mark=[1]), kv=KV([['POST /logout', '302 到 /login?logout,session 在服务端作废'], ['旧 cookie', '再访问被跳回 /login'], ['cookie 本身', '服务端没有下发删除指令'], ['CSRF', 'logout 默认要 POST 加令牌']], ['POST /logout'])),
]
A = mkartx('x105', 105, 'Spring,Security,Session,SecurityContextRepository,登录态,真实验证,动画演示',
    '实测 Spring Security 7 的登录态:表单登录后 SecurityContext 存在服务端 HttpSession 的 SPRING_SECURITY_CONTEXT,cookie 只有 JSESSIONID(HttpOnly);登录前后 session id 默认会变,关掉后不变;STATELESS 模式不创建会话;自己写登录接口只 setContext 而不 saveContext,下一个请求就没登录;退出后旧 cookie 失效。',
    '登录态到底存在哪里?session id 登录后为什么会变?STATELESS 是什么效果?自己写的登录接口为什么下次请求又要登录?这篇在 Spring Boot 4.0.8、Spring Security 7 上手动带 cookie 逐步验证。',
    [('SPRING_SECURITY_CONTEXT', '登录态存在服务端 HttpSession 的这个属性里,cookie 里只有 session id'), ('302 vs 200', '自定义登录接口不保存 SecurityContext,随后 /who 是 302;保存之后是 200'), ('1800 秒', '默认 session 超时 maxInactiveInterval')],
    [('登录态在哪里', '<p>服务端 HttpSession;cookie 只有 JSESSIONID(HttpOnly,没有 Secure 与 SameSite)。</p>'),
     ('会话固定防护', '<p>默认登录后换 session id;none() 会让 id 不变。</p>'),
     ('无状态', '<p>STATELESS 不创建会话,每个请求都要带凭据。</p>'),
     ('自定义登录接口', '<p>要显式 saveContext 到 SecurityContextRepository,否则下个请求就没登录。</p>'),
     ('退出', '<p>POST /logout 让 session 作废,旧 cookie 再访问被跳回登录页。</p>')],
    steps,
    [ENV_X + '(Spring Security 7)。用户 alice / pw(spring.security.user.*);客户端是 Python http.client,不自动跟随重定向,手动保存并带上 JSESSIONID;表单登录的 CSRF 令牌从登录页面里解析;SecurityFilterChain 由 -Dx105.cfg 切换(default、fixnone、stateless)',
     '没有验证:Redis 等外部存储里的 Spring Session;并发会话控制(maximumSessions);session 超时之后的行为;remember-me(见第 114 篇);SameSite 与 Secure 的配置(server.servlet.session.cookie.*);集群里 session 粘性;会话固定攻击的实际演示;HttpSessionSecurityContextRepository 与 RequestAttributeSecurityContextRepository 的差别'],
    '登录态')
